// DINERO 30-oct-2026 09:00 · Periodo de gracia de la tarjeta (método V2)
// Metáfora: dentro de la tarjeta hay una PUERTA que frena el interés. Si dejas saldo, se cierra
// y cada moneda que entra (cada compra) arrastra un medidor rojo de interés desde el primer día.
// Sitios: A = la tarjeta por dentro (azul marino, luz arriba a la izquierda); B = la mesa con el café.
import React from 'react';
import {AbsoluteFill, Easing, interpolate, clamp, useS, en, golpe, sacudida, Etiqueta, Contador, Camara, Destello, Ondas, FONT} from './kit';

export const SUBS = {acento: '#FFC83D'};

const ORO = '#FFC83D';
const ROJO = '#FF4D4D';

// Momentos atados a palabras
const T_DENTRO = en('Dentro');
const T_PUERTA = en('puerta');
const T_GRACIA = en('gracia');
const T_FRENA = en('frena');
const T_COMPRAS = en('compras');
const T_CINC = en('cincuenta');
const T_CERRAR = en('cerrarse');
const T_OCHO = en('ochocientos');
const T_PRIMER = en('primer');
const T_VEINTI = en('veintidós');
const T_OCHENTA = en('ochenta');
const T_CAFE = en('café');
const T_TRES = en('tres');
const T_MES3 = en('mes', 3);
const T_VUELVA = en('vuelva');
const T_COMPLETO = en('completo');
const T_LEE = en('lee');
const T_ENVIA = en('Envíaselo');

// Cuánto está abierta la puerta (1 abierta, 0 cerrada)
const abierta = (s: number) => {
  const cierra = interpolate(s, [T_CERRAR - 0.05, T_CERRAR + 0.35], [1, 0], {...clamp, easing: Easing.in(Easing.back(2))});
  const abre = interpolate(s, [T_COMPLETO, T_COMPLETO + 0.7], [0, 1], {...clamp, easing: Easing.out(Easing.back(1.6))});
  return Math.min(1, cierra + abre);
};

const FondoSitio: React.FC<{tono: [string, string, string]}> = ({tono}) => {
  const {s} = useS();
  return (
    <AbsoluteFill style={{background: `radial-gradient(ellipse at 28% 22%, ${tono[0]} 0%, ${tono[1]} 48%, ${tono[2]} 100%)`}}>
      {/* luz única arriba a la izquierda */}
      <div style={{position: 'absolute', left: -200, top: -260, width: 900, height: 900, borderRadius: 900, background: 'radial-gradient(circle, rgba(255,220,150,0.16), transparent 65%)'}} />
      {/* textura: líneas finas de circuito al fondo */}
      <svg width={1080} height={1920} style={{position: 'absolute', opacity: 0.16}}>
        {Array.from({length: 16}).map((_, i) => (
          <path key={i} d={`M ${(i * 97) % 1080} ${1920 - ((i * 131) % 600)} l 0 -${120 + (i % 5) * 60} l ${i % 2 ? 80 : -80} -60 l 0 -${200 + (i % 3) * 90}`} stroke="#7fb8ff" strokeWidth={3} fill="none" />
        ))}
      </svg>
      {/* bokeh delante desenfocado */}
      {Array.from({length: 9}).map((_, i) => {
        const r = 90 + ((i * 47) % 120);
        return <div key={i} style={{position: 'absolute', left: ((i * 233) % 1180) - 60 + Math.sin(s * 0.35 + i) * 30, top: ((i * 389) % 1900) + Math.cos(s * 0.3 + i) * 40, width: r, height: r, borderRadius: r, background: i % 3 ? 'rgba(120,170,255,0.10)' : 'rgba(255,200,61,0.10)', filter: 'blur(22px)'}} />;
      })}
      <AbsoluteFill style={{background: 'radial-gradient(circle at 50% 50%, transparent 52%, rgba(0,0,0,0.65) 100%)'}} />
    </AbsoluteFill>
  );
};

// Moneda con volumen: luz arriba a la izquierda, borde oscuro, brillo y sombra
const Moneda: React.FC<{x: number; y: number; r?: number; alpha?: number; medidor?: number}> = ({x, y, r = 46, alpha = 1, medidor = 0}) => (
  <g transform={`translate(${x} ${y})`} opacity={alpha}>
    <ellipse cx={6} cy={r + 14} rx={r * 0.9} ry={10} fill="rgba(0,0,0,0.35)" />
    <circle r={r} fill="url(#monedaG)" stroke="#a8761a" strokeWidth={5} />
    <circle r={r * 0.68} fill="none" stroke="rgba(120,80,10,0.55)" strokeWidth={4} />
    <text y={r * 0.3} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={r * 0.9} fill="#8a5a08">$</text>
    <ellipse cx={-r * 0.38} cy={-r * 0.42} rx={r * 0.28} ry={r * 0.16} fill="rgba(255,255,255,0.65)" />
    {medidor > 0 && (
      <g opacity={medidor}>
        <circle r={r + 12} fill="none" stroke={ROJO} strokeWidth={7} strokeDasharray={`${(r + 12) * 6.28 * medidor} 999`} transform="rotate(-90)" />
        <circle cx={r * 0.8} cy={-r * 0.8} r={16} fill={ROJO} />
      </g>
    )}
  </g>
);

const Defs: React.FC = () => (
  <defs>
    <radialGradient id="monedaG" cx="35%" cy="30%" r="75%">
      <stop offset="0%" stopColor="#fff2b0" />
      <stop offset="45%" stopColor={ORO} />
      <stop offset="100%" stopColor="#b9821c" />
    </radialGradient>
    <linearGradient id="tarjetaG" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0%" stopColor="#2f5fa8" />
      <stop offset="55%" stopColor="#173a73" />
      <stop offset="100%" stopColor="#0b1d40" />
    </linearGradient>
    <linearGradient id="chipG" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0%" stopColor="#fff0b8" />
      <stop offset="50%" stopColor={ORO} />
      <stop offset="100%" stopColor="#9a6a12" />
    </linearGradient>
    <linearGradient id="puertaG" x1="0" y1="0" x2="1" y2="0">
      <stop offset="0%" stopColor="#ffe28a" />
      <stop offset="100%" stopColor="#c48d1e" />
    </linearGradient>
    <linearGradient id="puertaR" x1="0" y1="0" x2="1" y2="0">
      <stop offset="0%" stopColor="#ff8a8a" />
      <stop offset="100%" stopColor="#b02a2a" />
    </linearGradient>
  </defs>
);

// La tarjeta gigante con la puerta adentro
const Tarjeta: React.FC = () => {
  const {s} = useS();
  const a = abierta(s);
  const golpePuerta = golpe(s, T_CERRAR + 0.3, 30, 6);
  const rojo = 1 - a;
  // monedas que cruzan la puerta de izquierda a derecha (compras)
  const monedas = Array.from({length: 9}).map((_, i) => {
    const ciclo = 2.4;
    const p = ((s + i * (ciclo / 9)) % ciclo) / ciclo;
    const x = 120 + p * 840;
    const y = 1150 + Math.sin(p * Math.PI * 2 + i) * 18;
    const cerca = Math.abs(x - 540) < 60;
    const tieneMedidor = s > T_CERRAR && x > 540 && s < T_COMPLETO ? Math.min(1, (x - 540) / 120) : 0;
    const vis = interpolate(s, [T_COMPRAS - 0.2, T_COMPRAS + 0.2], [0.55, 1], clamp) * (cerca && a < 0.3 ? 0.4 : 1);
    return <Moneda key={i} x={x} y={y} r={40} alpha={vis} medidor={tieneMedidor} />;
  });
  return (
    <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{position: 'absolute'}}>
      <Defs />
      {/* sombra proyectada */}
      <ellipse cx={560} cy={1450} rx={430} ry={46} fill="rgba(0,0,0,0.4)" style={{filter: 'blur(14px)'}} />
      <g transform="rotate(-5 540 1100)">
        <rect x={90} y={820} width={900} height={570} rx={48} fill="url(#tarjetaG)" stroke="#0a1838" strokeWidth={8} />
        <rect x={98} y={828} width={884} height={110} rx={44} fill="rgba(255,255,255,0.10)" />
        <path d="M 140 860 Q 400 830 700 870" stroke="rgba(255,255,255,0.35)" strokeWidth={10} fill="none" strokeLinecap="round" />
        <rect x={160} y={900} width={150} height={112} rx={18} fill="url(#chipG)" stroke="#8a5a08" strokeWidth={4} />
        <path d="M 160 956 L 310 956 M 235 900 L 235 1012" stroke="#8a5a08" strokeWidth={3} />
        {/* marco de la puerta */}
        <path d="M 400 1330 L 400 1040 Q 540 930 680 1040 L 680 1330 Z" fill="#06122b" stroke={rojo > 0.5 ? ROJO : ORO} strokeWidth={10} />
        <g transform={`translate(${golpePuerta * 10} 0)`}>
          <path d={`M 404 1330 L 404 1044 Q 470 990 540 980 L ${540 - 136 * a} 980 L ${540 - 136 * a} 1330 Z`} fill={rojo > 0.5 ? 'url(#puertaR)' : 'url(#puertaG)'} stroke="rgba(0,0,0,0.35)" strokeWidth={4} />
          <path d={`M 676 1330 L 676 1044 Q 610 990 540 980 L ${540 + 136 * a} 980 L ${540 + 136 * a} 1330 Z`} fill={rojo > 0.5 ? 'url(#puertaR)' : 'url(#puertaG)'} stroke="rgba(0,0,0,0.35)" strokeWidth={4} />
        </g>
        <rect x={160} y={1250} width={300} height={22} rx={11} fill="rgba(255,255,255,0.25)" />
        <rect x={160} y={1290} width={190} height={22} rx={11} fill="rgba(255,255,255,0.18)" />
      </g>
      {monedas}
    </svg>
  );
};

// Barra "pagado" del gancho: casi llena, con un pedacito rojo que queda
const BarraPago: React.FC = () => {
  const {s, lin} = useS();
  const lleno = lin(0, 1.1, 0.35, 0.94, Easing.out(Easing.cubic));
  const vis = lin(T_DENTRO - 0.4, T_DENTRO, 1, 0);
  if (vis <= 0) return null;
  const late = 1 + 0.08 * Math.max(0, Math.sin(s * 7));
  return (
    <div style={{position: 'absolute', left: 140, top: 1560, width: 800, height: 70, borderRadius: 40, background: 'rgba(5,12,30,0.85)', border: '4px solid rgba(255,255,255,0.25)', opacity: vis, overflow: 'hidden'}}>
      <div style={{position: 'absolute', left: 0, top: 0, bottom: 0, width: `${lleno * 100}%`, background: `linear-gradient(180deg, #ffe596, ${ORO} 55%, #b9821c)`}} />
      <div style={{position: 'absolute', right: 0, top: 0, bottom: 0, width: `${(1 - lleno) * 100}%`, background: `linear-gradient(180deg, #ff9a9a, ${ROJO})`, transform: `scaleY(${late})`}} />
    </div>
  );
};

// Sitio B: taza de café que se vacía, un sorbo por día, hacia la boca roja del interés
const Taza: React.FC = () => {
  const {s, spr, lin} = useS();
  const entra = spr(T_CAFE - 0.1, 12, 150);
  const nivel = lin(T_TRES, T_MES3 + 0.4, 1, 0.08);
  const vapor = Array.from({length: 3}).map((_, i) => (
    <path key={i} d={`M ${470 + i * 70} ${960 - ((s * 60 + i * 40) % 120)} q 30 -40 0 -80 q -30 -40 0 -80`} stroke="rgba(255,255,255,0.45)" strokeWidth={12} fill="none" strokeLinecap="round" opacity={0.6} />
  ));
  const gotas = Array.from({length: 8}).map((_, i) => {
    const t = s - T_TRES - i * 0.22;
    if (t < 0 || t > 0.9 || s > T_VUELVA) return null;
    return <Moneda key={i} x={700 + t * 220} y={1180 - Math.sin(t * Math.PI) * 220 + t * 140} r={24} />;
  });
  return (
    <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{position: 'absolute', transform: `scale(${0.6 + 0.4 * entra})`, transformOrigin: '540px 1200px'}}>
      <Defs />
      <defs>
        <linearGradient id="tazaG" x1="0" y1="0" x2="1" y2="0">
          <stop offset="0%" stopColor="#ffffff" />
          <stop offset="70%" stopColor="#d9e2f2" />
          <stop offset="100%" stopColor="#9aa8c4" />
        </linearGradient>
      </defs>
      <ellipse cx={560} cy={1470} rx={330} ry={40} fill="rgba(0,0,0,0.45)" style={{filter: 'blur(12px)'}} />
      <rect x={140} y={1440} width={800} height={30} rx={15} fill="#4a2f1f" />
      {vapor}
      <path d="M 330 1010 L 360 1420 Q 540 1470 720 1420 L 750 1010 Z" fill="url(#tazaG)" stroke="#6e7b96" strokeWidth={6} />
      <path d="M 750 1100 q 120 10 110 130 q -10 110 -125 100" stroke="#c9d3e6" strokeWidth={34} fill="none" />
      <clipPath id="liq"><path d="M 336 1030 L 362 1410 Q 540 1455 718 1410 L 744 1030 Z" /></clipPath>
      <rect x={330} y={1030 + (1 - nivel) * 380} width={430} height={400} fill="#6b3b1f" clipPath="url(#liq)" />
      <ellipse cx={540} cy={1010} rx={210} ry={34} fill="#5a3218" stroke="#6e7b96" strokeWidth={6} />
      <ellipse cx={420} cy={1150} rx={22} ry={110} fill="rgba(255,255,255,0.55)" />
      {/* boca roja del interés */}
      <g transform={`translate(960 1330) scale(${spr(T_TRES, 10, 180)})`}>
        <circle r={90} fill={ROJO} stroke="#8e1d1d" strokeWidth={6} />
        <path d={`M -50 10 Q 0 ${40 + Math.abs(Math.sin(s * 8)) * 30} 50 10 Z`} fill="#3a0b0b" />
        <circle cx={-30} cy={-30} r={12} fill="#3a0b0b" />
        <circle cx={30} cy={-30} r={12} fill="#3a0b0b" />
        <ellipse cx={-40} cy={-58} rx={22} ry={10} fill="rgba(255,255,255,0.5)" />
      </g>
      {gotas}
    </svg>
  );
};

const Avion: React.FC = () => {
  const {lin} = useS();
  const p = lin(T_ENVIA + 0.1, T_ENVIA + 1.6, 0, 1, Easing.in(Easing.quad));
  if (p <= 0 || p >= 1) return null;
  return (
    <svg width={170} height={170} viewBox="0 0 100 100" style={{position: 'absolute', left: 560 + p * 520, top: 1300 - p * 900 - Math.sin(p * Math.PI) * 160, transform: `rotate(-28deg) scale(${1.1 - p * 0.5})`}}>
      <polygon points="5,50 95,10 60,90 48,58" fill="#ffffff" />
      <polygon points="48,58 95,10 40,70" fill="#b9c8ea" />
    </svg>
  );
};

export const Escena: React.FC = () => {
  const {s, lin} = useS();
  const sh = sacudida(s, [T_CERRAR + 0.3, T_PRIMER], 14);
  // corte A -> B en "café" y B -> A en "vuelva"
  const enB = s >= T_CAFE - 0.02 && s < T_VUELVA - 0.02;
  const deriva = Math.sin(s * 0.6) * 14;
  const paradas = [
    {t: 0, x: 540, y: 1120, zoom: 1.0},
    {t: T_DENTRO - 0.1, x: 540, y: 1110, zoom: 1.08},
    {t: T_PUERTA + 0.3, x: 540, y: 1150, zoom: 1.9},
    {t: T_FRENA + 0.3, x: 560, y: 1160, zoom: 1.75},
    {t: T_CINC, x: 540, y: 1140, zoom: 1.35},
    {t: T_CERRAR + 0.3, x: 540, y: 1160, zoom: 1.6},
    {t: T_OCHO + 0.4, x: 620, y: 1150, zoom: 1.3},
    {t: T_VEINTI, x: 600, y: 1130, zoom: 1.15},
    {t: T_CAFE - 0.05, x: 560, y: 1120, zoom: 1.1},
  ];
  const paradasFin = [
    {t: T_VUELVA, x: 540, y: 1120, zoom: 1.25},
    {t: T_COMPLETO + 0.5, x: 540, y: 1150, zoom: 1.7},
    {t: T_LEE, x: 540, y: 1120, zoom: 1.2},
    {t: T_ENVIA + 1.5, x: 540, y: 1100, zoom: 0.95},
  ];
  return (
    <AbsoluteFill>
      <FondoSitio tono={enB ? ['#1d4a3c', '#0e2a22', '#04110d'] : ['#21407a', '#0f2148', '#050b1c']} />
      <AbsoluteFill style={{transform: `translate(${sh.x + deriva}px, ${sh.y}px)`}}>
        {!enB && (
          <Camara paradas={s < T_VUELVA ? paradas : paradasFin} centroY={1080}>
            <Tarjeta />
            <Ondas x={540} y={1150} t0={T_CERRAR + 0.3} color={ROJO} />
            <Ondas x={540} y={1150} t0={T_COMPLETO + 0.2} color={ORO} />
            {s > T_GRACIA - 0.1 && s < T_CINC && <Etiqueta texto="gracia" x={800} y={930} px={600} py={1000} t0={T_GRACIA} color={ORO} />}
          </Camara>
        )}
        {enB && <Taza />}
        <BarraPago />
        <Avion />
      </AbsoluteFill>
      {/* números que se mueven: arriba, bajo la franja de subtítulos */}
      {s >= T_CINC && s < T_OCHO && <Contador desde={0} hasta={50} t0={T_CINC} t1={T_CINC + 0.6} y={430} prefijo="$" color={ROJO} />}
      {s >= T_OCHO && s < T_VEINTI && <Contador desde={0} hasta={800} t0={T_OCHO} t1={T_PRIMER + 0.3} y={430} prefijo="$" color={ORO} />}
      {s >= T_VEINTI && s < T_OCHENTA && <Contador desde={0} hasta={22} t0={T_VEINTI} t1={T_VEINTI + 0.6} y={430} sufijo="%" color={ROJO} />}
      {s >= T_OCHENTA && s < T_CAFE && <Contador desde={0} hasta={87} t0={T_OCHENTA} t1={T_OCHENTA + 0.9} y={430} prefijo="$" color={ROJO} />}
      {enB && s >= T_TRES && <Contador desde={0} hasta={30} t0={T_TRES} t1={T_MES3 + 0.3} y={430} sufijo=" días" color={ORO} />}
      <Destello t0={T_CERRAR + 0.3} fuerza={0.35} />
      <Destello t0={T_COMPLETO + 0.1} fuerza={0.4} />
      {/* viñeta y resplandor final */}
      <AbsoluteFill style={{pointerEvents: 'none', background: `radial-gradient(circle at 50% 58%, rgba(255,200,61,${0.08 * lin(T_COMPLETO, T_COMPLETO + 0.6, 0, 1)}), transparent 60%)`}} />
    </AbsoluteFill>
  );
};
